def count_lengths(names):
    out = {}
    for name in names:
        out[name] = len(name)
    return out

def unique_count(names):
    return len(set(names))

def total_evens(nums):
    total = 0
    for n in nums:
        if n % 2 == 0:
            total += n
    return total

def count_down(n):
    return list(range(n, 0, -1))

